CREATE OR REPLACE FUNCTION public.sync_profile_email_from_auth()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = public, pg_catalog
AS $function$
BEGIN
  IF current_setting('quantalyze.sanitize_in_progress', true) = 'on' THEN
